PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
        id TEXT PRIMARY KEY,
        username TEXT NOT NULL,
        avatar TEXT,
        role TEXT DEFAULT 'user',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      , roblox_username TEXT, bio TEXT);
CREATE TABLE vehicles (
      id TEXT PRIMARY KEY,
      owner_id TEXT NOT NULL,
      maker TEXT NOT NULL,
      model TEXT NOT NULL,
      year INTEGER NOT NULL,
      trim TEXT,
      color TEXT,
      plate TEXT NOT NULL,
      roblox_username TEXT,
      status TEXT DEFAULT 'pending',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , plate_region TEXT, image_data TEXT, reject_reason TEXT, vehicle_type TEXT, trailer_type TEXT, temp_plate TEXT, temp_expires_at TEXT, requested_temp_plate TEXT, is_temp_registration TEXT, reviewed_at TEXT, game_type TEXT);
CREATE TABLE questions (id TEXT PRIMARY KEY, sort_order INTEGER NOT NULL, question TEXT NOT NULL, type TEXT NOT NULL, choices TEXT, answer TEXT, is_active INTEGER DEFAULT 1, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE, roblox_username TEXT NOT NULL, discord_username TEXT NOT NULL, status TEXT DEFAULT 'pending', answers TEXT NOT NULL, auto_score INTEGER, auto_score_max INTEGER, reject_reason TEXT, submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME, reviewed_by TEXT);
CREATE TABLE vehicle_catalog (
  id TEXT PRIMARY KEY,
  data TEXT NOT NULL,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_push_tokens (
      user_id TEXT NOT NULL,
      token TEXT NOT NULL,
      platform TEXT NOT NULL,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, results_enabled INTEGER DEFAULT 1, admin_enabled INTEGER DEFAULT 1, admin_edit_enabled INTEGER DEFAULT 1, timeline_like_enabled INTEGER DEFAULT 1, timeline_comment_enabled INTEGER DEFAULT 1, timeline_new_post_enabled INTEGER DEFAULT 1, device_id TEXT,
      PRIMARY KEY (user_id, token)
    );
CREATE TABLE timeline_posts (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      content TEXT NOT NULL,
      image_data TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , views_count INTEGER DEFAULT 0, video_path TEXT, repost_id TEXT, is_announcement INTEGER DEFAULT 0);
CREATE TABLE timeline_likes (
      post_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      PRIMARY KEY (post_id, user_id)
    );
CREATE TABLE notifications (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      title TEXT NOT NULL,
      body TEXT NOT NULL,
      type TEXT NOT NULL,
      link_action TEXT,
      is_read INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE timeline_comments (
      id TEXT PRIMARY KEY,
      post_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , parent_id TEXT, image_data TEXT, video_path TEXT, views_count INTEGER DEFAULT 0);
CREATE TABLE timeline_comment_likes (
      comment_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      PRIMARY KEY (comment_id, user_id)
    );
CREATE TABLE timeline_views (
      post_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      PRIMARY KEY (post_id, user_id)
    );
CREATE TABLE follows (
      follower_id TEXT,
      following_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY (follower_id, following_id)
    );
CREATE TABLE search_dictionary (
      kana TEXT PRIMARY KEY,
      candidates TEXT NOT NULL
    );
CREATE TABLE timeline_polls (
      post_id TEXT PRIMARY KEY,
      options TEXT NOT NULL,
      expires_at DATETIME NOT NULL
    , allow_multiple INTEGER DEFAULT 0);
CREATE TABLE timeline_pins (
      user_id TEXT PRIMARY KEY,
      post_id TEXT NOT NULL
    );
CREATE TABLE timeline_bookmarks (
      user_id TEXT,
      post_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY (user_id, post_id)
    );
CREATE TABLE timeline_poll_votes (
      user_id TEXT,
      post_id TEXT,
      option_index INTEGER,
      PRIMARY KEY (user_id, post_id, option_index)
    );
CREATE TABLE user_passkeys (
      credential_id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      public_key TEXT NOT NULL,
      counter INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP, key_name TEXT,
      FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
    );
